require('dotenv').config();

const { CredentialManager } = require('./utils/credential-manager');
const { Database } = require('./database/db');
const { Logger } = require('./utils/logger');
const chalk = require('chalk');
const inquirer = require('inquirer');
const fs = require('fs').promises;
const path = require('path');

class YouTubeAutomationSetup {
  constructor() {
    this.logger = new Logger('Setup');
    this.credentialManager = new CredentialManager();
    this.database = new Database();
  }

  async run() {
    console.log(chalk.cyan.bold('\n🎬 YouTube Automation Agent Setup'));
    console.log(chalk.gray('═'.repeat(60)));
    console.log(chalk.cyan('Welcome to the YouTube Automation Agent setup wizard!'));
    console.log(chalk.gray('This will configure your system for fully automated YouTube content creation.\n'));

    const { mode } = await inquirer.prompt([{
      type: 'list',
      name: 'mode',
      message: 'How would you like to set up?',
      choices: [
        { name: '🧭 Guided walkthrough — explains everything, tests keys as you go (recommended for first-timers)', value: 'walkthrough' },
        { name: '⚡ Classic quick setup — for users who already have all their keys', value: 'classic' }
      ]
    }]);

    if (mode === 'walkthrough') {
      const { SetupWalkthrough } = require('./walkthrough');
      return await new SetupWalkthrough().run();
    }

    try {
      // Step 1: Create directories
      await this.createDirectories();

      // Step 2: Initialize database
      await this.initializeDatabase();

      // Step 3: Run credential setup
      await this.credentialManager.runSetupWizard();

      // Step 4: Create environment file
      await this.createEnvironmentFile();

      // Step 5: Install additional dependencies if needed
      await this.installDependencies();

      // Step 6: Create startup scripts
      await this.createStartupScripts();

      // Step 7: Final validation
      await this.validateSetup();

      console.log(chalk.green.bold('\n🎉 Setup completed successfully!'));
      console.log(chalk.cyan('\n📋 Next steps:'));
      console.log(chalk.white('1. Run: npm start'));
      console.log(chalk.white('2. Visit: http://localhost:3456'));
      console.log(chalk.white('3. Your first video will be generated and scheduled within 24 hours'));

      console.log(chalk.gray('\n═'.repeat(60)));
      console.log(chalk.yellow('🤖 Your YouTube channel is now fully automated!'));

    } catch (error) {
      console.log(chalk.red.bold('\n❌ Setup failed!'));
      console.log(chalk.red(error.message));
      process.exit(1);
    }
  }

  async createDirectories() {
    console.log(chalk.cyan('\n📁 Creating directory structure...'));

    const directories = [
      'config',
      'logs',
      'data',
      'data/production',
      'data/assets',
      'data/videos',
      'data/audio',
      'data/scripts',
      'data/captions',
      'data/thumbnail-templates',
      'temp/processing',
      'uploads/thumbnails'
    ];

    for (const dir of directories) {
      const fullPath = path.join(__dirname, dir);
      await fs.mkdir(fullPath, { recursive: true });
      console.log(chalk.gray(`  ✓ Created: ${dir}`));
    }

    console.log(chalk.green('✅ Directory structure created'));
  }

  async initializeDatabase() {
    console.log(chalk.cyan('\n🗄️  Initializing database...'));

    await this.database.initialize();

    console.log(chalk.green('✅ Database initialized'));
  }

  async createEnvironmentFile() {
    console.log(chalk.cyan('\n🔧 Creating environment configuration...'));

    const envContent = `# YouTube Automation Agent Environment Configuration
# Generated on ${new Date().toISOString()}

# Application Settings
NODE_ENV=production
PORT=3456
LOG_LEVEL=info

# YouTube Settings
YOUTUBE_REGION=US
DEFAULT_PRIVACY_STATUS=private

# Content Settings
AUTO_SHORTEN_CONTENT=true
AUTO_ADD_BACKLINKS=true
PRESERVE_FORMATTING=true
AUTO_RESIZE_IMAGES=true
MAX_IMAGE_WIDTH=1280
MAX_IMAGE_HEIGHT=720
IMAGE_QUALITY=90

# Rate Limiting
GLOBAL_RATE_LIMIT_PER_HOUR=50
DEFAULT_DELAY_BETWEEN_POSTS=60000

# TTS Settings
TTS_VOICE=neural_voice_1

# Analytics & Monitoring
ENABLE_ANALYTICS=true
ANALYTICS_DB_PATH=./data/analytics.db

# File Upload Settings
MAX_FILE_SIZE=52428800
UPLOAD_PATH=./uploads

# Error Handling
RETRY_ATTEMPTS=3
RETRY_DELAY=5000

# Automation Settings
DAILY_CONTENT_ENABLED=true
AUTO_PUBLISH_ENABLED=true
OPTIMIZATION_ENABLED=true
CONTENT_BUFFER_DAYS=3
MAX_DAILY_POSTS=1

# Notification Settings
NOTIFICATION_ENABLED=true

# Debug Settings (Development only)
DEBUG_MODE=false
VERBOSE_LOGGING=false
SAVE_SCREENSHOTS=false
SCREENSHOT_PATH=./debug/screenshots
`;

    await fs.writeFile(path.join(__dirname, '.env'), envContent);
    console.log(chalk.green('✅ Environment file created'));
  }


  async installDependencies() {
    console.log(chalk.cyan('\n📦 Checking dependencies...'));

    try {
      // Check if package.json exists and dependencies are installed
      const nodeModulesPath = path.join(__dirname, 'node_modules');

      try {
        await fs.access(nodeModulesPath);
        console.log(chalk.green('✅ Dependencies already installed'));
      } catch (error) {
        console.log(chalk.yellow('⚠️  Dependencies not installed. Please run: npm install'));
      }
    } catch (error) {
      console.log(chalk.yellow('⚠️  Could not verify dependencies'));
    }
  }

  async createStartupScripts() {
    console.log(chalk.cyan('\n🚀 Creating startup scripts...'));

    // Create Windows batch file
    const windowsScript = `@echo off
echo Starting YouTube Automation Agent...
node index.js
pause`;

    await fs.writeFile(path.join(__dirname, 'start.bat'), windowsScript);

    // Create Unix shell script
    const unixScript = `#!/bin/bash
echo "Starting YouTube Automation Agent..."
node index.js`;

    await fs.writeFile(path.join(__dirname, 'start.sh'), unixScript);

    // Create PM2 ecosystem file for production
    const pm2Config = {
      apps: [{
        name: 'youtube-automation-agent',
        script: 'index.js',
        instances: 1,
        autorestart: true,
        watch: false,
        max_memory_restart: '1G',
        env: {
          NODE_ENV: 'production',
          PORT: 3456
        }
      }]
    };

    await fs.writeFile(
      path.join(__dirname, 'ecosystem.config.js'), 
      `module.exports = ${JSON.stringify(pm2Config, null, 2)};`
    );

    console.log(chalk.green('✅ Startup scripts created'));
  }

  async validateSetup() {
    console.log(chalk.cyan('\n🔍 Validating setup...'));

    const validation = {
      directories: true,
      database: false,
      credentials: false,
      environment: false,
      ffmpeg: false
    };

    // Check directories
    try {
      await fs.access(path.join(__dirname, 'data'));
      await fs.access(path.join(__dirname, 'logs'));
      await fs.access(path.join(__dirname, 'config'));
    } catch (error) {
      validation.directories = false;
    }

    // Check database
    try {
      await this.database.getStats();
      validation.database = true;
    } catch (error) {
      validation.database = false;
    }

    // Check credentials
    validation.credentials = await this.credentialManager.validateAll();

    // Check environment
    try {
      await fs.access(path.join(__dirname, '.env'));
      validation.environment = true;
    } catch (error) {
      validation.environment = false;
    }

    // Check FFmpeg (needed for video assembly)
    const { checkFFmpeg, ffmpegInstallHint } = require('./utils/ffmpeg');
    validation.ffmpeg = await checkFFmpeg();

    // Display validation results
    Object.entries(validation).forEach(([component, valid]) => {
      const icon = valid ? '✅' : '❌';
      const color = valid ? chalk.green : chalk.red;
      console.log(color(`  ${icon} ${component}`));
    });

    // Only broken infrastructure is fatal — missing credentials/FFmpeg can be fixed later
    if (!validation.directories || !validation.database || !validation.environment) {
      throw new Error('Setup validation failed. Please check the errors above.');
    }

    if (!validation.credentials) {
      console.log(chalk.yellow('\n⚠️  Credentials are incomplete. Finish them any time with: npm run credentials:setup'));
    }

    if (!validation.ffmpeg) {
      console.log(chalk.yellow(`\n⚠️  ${ffmpegInstallHint()}`));
    }

    if (validation.credentials && validation.ffmpeg) {
      console.log(chalk.green('✅ All validations passed'));
    } else {
      console.log(chalk.yellow('✅ Core setup complete (with warnings above)'));
    }
  }

  async createSampleContent() {
    console.log(chalk.cyan('\n📝 Creating sample content templates...'));

    // Create sample script template
    const sampleScript = {
      title: "Getting Started with YouTube Automation",
      hook: {
        type: "question",
        text: "Have you ever wondered how top YouTubers manage to post consistently?"
      },
      introduction: {
        greeting: "Hey everyone, welcome back to the channel!",
        topicIntro: "Today, we're diving into YouTube automation.",
        valueProposition: "By the end of this video, you'll understand how automation can transform your channel."
      },
      mainContent: {
        sections: [
          {
            title: "What is YouTube Automation?",
            content: "YouTube automation is the process of using technology to handle repetitive tasks in content creation and channel management."
          },
          {
            title: "Benefits of Automation",
            content: "Automation saves time, ensures consistency, and allows you to focus on strategy rather than execution."
          }
        ]
      }
    };

    await fs.writeFile(
      path.join(__dirname, 'data', 'sample-script.json'),
      JSON.stringify(sampleScript, null, 2)
    );

    console.log(chalk.green('✅ Sample content created'));
  }
}

// Run setup if called directly
if (require.main === module) {
  const setup = new YouTubeAutomationSetup();
  setup.run().catch(error => {
    console.error(chalk.red('Setup failed:'), error);
    process.exit(1);
  });
}

module.exports = { YouTubeAutomationSetup };

const { google } = require('googleapis');
const fs = require('fs');
const path = require('path');
const chalk = require('chalk');
const http = require('http');
const { URL } = require('url');

class ModernAuth {
  constructor() {
    this.credentialsPath = path.join(__dirname, 'config', 'credentials.json');
    this.tokensPath = path.join(__dirname, 'config', 'tokens.json');
    this.server = null;
  }

  async authenticate() {
    console.log(chalk.cyan.bold('\n🔐 YouTube Authentication (Modern Flow)'));
    console.log(chalk.gray('═'.repeat(60)));

    try {
      const credentials = JSON.parse(fs.readFileSync(this.credentialsPath));

      // Use a random high port to avoid conflicts
      const port = 8000 + Math.floor(Math.random() * 1000);
      const redirectUri = `http://localhost:${port}/callback`;

      const oauth2Client = new google.auth.OAuth2(
        credentials.youtube.client_id,
        credentials.youtube.client_secret,
        redirectUri
      );

      const scopes = [
        'https://www.googleapis.com/auth/youtube.upload',
        'https://www.googleapis.com/auth/youtube',
        'https://www.googleapis.com/auth/youtube.readonly',
        'https://www.googleapis.com/auth/yt-analytics.readonly'
      ];

      // Start a temporary local server
      await this.startTempServer(port, oauth2Client);

      // Generate auth URL
      const authUrl = oauth2Client.generateAuthUrl({
        access_type: 'offline',
        scope: scopes,
        prompt: 'consent'
      });

      console.log(chalk.cyan('🔗 Please visit this URL to authorize:'));
      console.log(chalk.blue(authUrl));

      // Best effort: open the URL in the default browser
      const { exec } = require('child_process');
      const openCommands = {
        win32: `start "" "${authUrl}"`,
        darwin: `open "${authUrl}"`,
        linux: `xdg-open "${authUrl}"`
      };
      if (openCommands[process.platform]) {
        exec(openCommands[process.platform], () => {});
      }
      console.log(chalk.yellow(`\n⚡ A temporary server is running on port ${port}`));
      console.log(chalk.yellow('After authorization, you\'ll be redirected automatically.'));
      console.log(chalk.gray('Waiting for authorization...'));

      // The server will handle the rest
      return new Promise((resolve, reject) => {
        this.resolveAuth = resolve;
        this.rejectAuth = reject;

        // Set timeout
        setTimeout(() => {
          this.cleanup();
          reject(new Error('Authentication timeout (5 minutes)'));
        }, 300000); // 5 minutes
      });

    } catch (error) {
      console.error(chalk.red('Authentication failed:'), error.message);
      throw error;
    }
  }

  async startTempServer(port, oauth2Client) {
    this.server = http.createServer(async (req, res) => {
      const url = new URL(req.url, `http://localhost:${port}`);

      if (url.pathname === '/callback') {
        const code = url.searchParams.get('code');
        const error = url.searchParams.get('error');

        if (error) {
          res.writeHead(400, { 'Content-Type': 'text/html' });
          res.end(`
            <h1>❌ Authorization Error</h1>
            <p>${error}</p>
            <p>You can close this window.</p>
          `);
          this.rejectAuth(new Error(`Authorization error: ${error}`));
          return;
        }

        if (code) {
          try {
            const { tokens } = await oauth2Client.getToken(code);

            // Save tokens
            const tokenData = { youtube: tokens };
            fs.writeFileSync(this.tokensPath, JSON.stringify(tokenData, null, 2));

            res.writeHead(200, { 'Content-Type': 'text/html' });
            res.end(`
              <html>
                <body style="font-family: Arial, sans-serif; text-align: center; padding: 50px;">
                  <h1 style="color: #4CAF50;">🎉 Authentication Successful!</h1>
                  <p>Your YouTube Automation Agent has been authorized!</p>
                  <p><strong>"Ethereal Dreamscript"</strong> is ready for automation.</p>
                  <p>You can close this window and return to the terminal.</p>
                </body>
              </html>
            `);

            console.log(chalk.green('\n✅ Authentication successful!'));
            this.cleanup();
            this.resolveAuth(tokens);

          } catch (tokenError) {
            res.writeHead(500, { 'Content-Type': 'text/html' });
            res.end(`
              <h1>❌ Token Exchange Failed</h1>
              <p>${tokenError.message}</p>
            `);
            this.rejectAuth(tokenError);
          }
        }
      } else {
        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.end(`
          <html>
            <body style="font-family: Arial, sans-serif; text-align: center; padding: 50px;">
              <h1>🎬 YouTube Automation Agent</h1>
              <p>Waiting for OAuth callback...</p>
              <p>Please complete the authorization in the other tab.</p>
            </body>
          </html>
        `);
      }
    });

    this.server.listen(port, 'localhost');
    console.log(chalk.gray(`Temporary OAuth server started on port ${port}`));
  }

  cleanup() {
    if (this.server) {
      this.server.close();
      this.server = null;
    }
  }

  async testAuthentication() {
    try {
      const tokens = JSON.parse(fs.readFileSync(this.tokensPath));
      const credentials = JSON.parse(fs.readFileSync(this.credentialsPath));

      const oauth2Client = new google.auth.OAuth2(
        credentials.youtube.client_id,
        credentials.youtube.client_secret
      );

      oauth2Client.setCredentials(tokens.youtube);

      const youtube = google.youtube({ version: 'v3', auth: oauth2Client });
      const response = await youtube.channels.list({
        part: 'snippet',
        mine: true
      });

      if (response.data.items && response.data.items.length > 0) {
        const channel = response.data.items[0];
        console.log(chalk.green(`✅ Connected to channel: ${channel.snippet.title}`));
        console.log(chalk.gray(`   Channel ID: ${channel.id}`));
        console.log(chalk.gray(`   Subscribers: ${channel.statistics?.subscriberCount || 'Hidden'}`));
        return true;
      } else {
        console.log(chalk.red('❌ No channel found'));
        return false;
      }
    } catch (error) {
      console.error(chalk.red('Authentication test failed:'), error.message);
      return false;
    }
  }
}

async function runAuth() {
  const auth = new ModernAuth();

  try {
    await auth.authenticate();

    console.log(chalk.cyan('\n🧪 Testing authentication...'));
    const success = await auth.testAuthentication();

    if (success) {
      console.log(chalk.green.bold('\n🎉 Authentication Complete!'));
      console.log(chalk.cyan('Your "Ethereal Dreamscript" YouTube automation is ready!'));
      console.log(chalk.yellow('\n📋 Next Steps:'));
      console.log(chalk.white('1. Run: npm start'));
      console.log(chalk.white('2. Visit: http://localhost:3456'));
      console.log(chalk.white('3. Your first video will be generated within 24 hours!'));
    } else {
      console.log(chalk.red('\n❌ Authentication test failed.'));
    }
  } catch (error) {
    console.error(chalk.red('\nAuthentication failed:'), error.message);
    if (error.message.includes('timeout')) {
      console.log(chalk.yellow('\n💡 Try again - the authorization window might have closed.'));
    }
    process.exit(1);
  }
}

if (require.main === module) {
  runAuth();
}

module.exports = { ModernAuth };

const express = require('express');
const { google } = require('googleapis');
const fs = require('fs');
const path = require('path');
const chalk = require('chalk');

class OAuthServer {
  constructor() {
    this.app = express();
    this.server = null;
    this.setupRoutes();
  }

  setupRoutes() {
    this.app.get('/auth/callback', async (req, res) => {
      const { code, error } = req.query;

      if (error) {
        res.send(`<h1>❌ Authentication Error</h1><p>${error}</p>`);
        return;
      }

      if (!code) {
        res.send(`<h1>❌ No Authorization Code</h1><p>No authorization code received</p>`);
        return;
      }

      try {
        // Exchange code for tokens
        await this.exchangeCodeForTokens(code);

        res.send(`
          <h1>🎉 Authentication Successful!</h1>
          <p>Your YouTube Automation Agent has been successfully authorized!</p>
          <p>You can close this window and return to the terminal.</p>
          <style>
            body { font-family: Arial, sans-serif; text-align: center; padding: 50px; }
            h1 { color: #4CAF50; }
          </style>
        `);

        console.log(chalk.green('\n✅ Authentication successful! Starting YouTube Automation Agent...'));

        // Close the server after successful auth
        setTimeout(() => {
          this.server.close();
          this.startMainApplication();
        }, 2000);

      } catch (error) {
        console.error(chalk.red('Token exchange failed:'), error);
        res.send(`<h1>❌ Token Exchange Failed</h1><p>${error.message}</p>`);
      }
    });

    this.app.get('/', (req, res) => {
      res.send(`
        <h1>🎬 YouTube Automation Agent</h1>
        <p>OAuth callback server is running...</p>
        <p>Please complete the authorization process.</p>
        <style>
          body { font-family: Arial, sans-serif; text-align: center; padding: 50px; }
        </style>
      `);
    });
  }

  async exchangeCodeForTokens(code) {
    const credentialsPath = path.join(__dirname, 'config', 'credentials.json');
    const tokensPath = path.join(__dirname, 'config', 'tokens.json');

    const credentials = JSON.parse(fs.readFileSync(credentialsPath));

    const oauth2Client = new google.auth.OAuth2(
      credentials.youtube.client_id,
      credentials.youtube.client_secret,
      credentials.youtube.redirect_uris[0]
    );

    const { tokens } = await oauth2Client.getToken(code);

    // Save tokens
    const tokenData = {
      youtube: tokens
    };

    fs.writeFileSync(tokensPath, JSON.stringify(tokenData, null, 2));
    console.log(chalk.green('✅ Tokens saved successfully!'));
  }

  async startMainApplication() {
    console.log(chalk.cyan('\n🚀 Starting YouTube Automation Agent...'));

    // Import and start the main application
    const { spawn } = require('child_process');
    const mainApp = spawn('node', ['index.js'], {
      stdio: 'inherit',
      cwd: __dirname
    });

    mainApp.on('close', (code) => {
      console.log(chalk.yellow(`Main application exited with code ${code}`));
    });
  }

  start() {
    this.server = this.app.listen(8080, () => {
      console.log(chalk.cyan('\n🔐 OAuth callback server started on http://localhost:8080'));
      this.generateAuthUrl();
    });
  }

  generateAuthUrl() {
    const credentialsPath = path.join(__dirname, 'config', 'credentials.json');
    const credentials = JSON.parse(fs.readFileSync(credentialsPath));

    const oauth2Client = new google.auth.OAuth2(
      credentials.youtube.client_id,
      credentials.youtube.client_secret,
      credentials.youtube.redirect_uris[0]
    );

    const scopes = [
      'https://www.googleapis.com/auth/youtube.upload',
      'https://www.googleapis.com/auth/youtube',
      'https://www.googleapis.com/auth/youtube.readonly',
      'https://www.googleapis.com/auth/yt-analytics.readonly'
    ];

    const authUrl = oauth2Client.generateAuthUrl({
      access_type: 'offline',
      scope: scopes,
      prompt: 'consent'
    });

    console.log(chalk.cyan.bold('\n🎬 YouTube Automation Agent - OAuth Setup'));
    console.log(chalk.gray('═'.repeat(60)));
    console.log(chalk.cyan('\n🔗 Please visit this URL to authorize the application:'));
    console.log(chalk.blue.underline(authUrl));
    console.log(chalk.yellow('\nAfter authorization, you will be redirected back automatically.'));
    console.log(chalk.gray('The OAuth server will handle the rest!'));
  }
}

if (require.main === module) {
  const oauthServer = new OAuthServer();
  oauthServer.start();
}

module.exports = { OAuthServer };

